// Access resource metrics:
time_t user_sec = usage.ru_utime.tv_sec;
long sys_usec = usage.ru_stime.tv_usec;

long max_mem_kb = usage.ru_maxrss;   // Max Resident Set Size (KB)
long major_faults = usage.ru_majflt; // Major page faults
long voluntary_switches = usage.ru_nvcsw;
